def traversals(values):
    def insert(node, value):
        if node is None:
            return [value, None, None]
        if value < node[0]:
            node[1] = insert(node[1], value)
        elif value > node[0]:
            node[2] = insert(node[2], value)
        return node
    root = None
    for value in values:
        root = insert(root, value)
    pre, ino, post = [], [], []
    def walk(node):
        if node is None:
            return
        pre.append(node[0])
        walk(node[1])
        ino.append(node[0])
        walk(node[2])
        post.append(node[0])
    walk(root)
    return [pre, ino, post]
